options.getOption:
// When each station has data: one row per station, north at the top, a bar for
// every unbroken run of daily positions in the catalog. The band is the window;
// a station needs data at both of its edges to get an arrow, which is why some
// dots on the map stay grey. The chosen station is drawn in orange.
//
// Click a row to choose that station.

// @constants begin
const VAR = 'station';
const STATION = '${station}'; // written out: a new station redraws the chart
const FROM = '${__from}';
const TO = '${__to}';
const COLOR_ON = 'blue';
const COLOR_PICKED = 'orange';
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const ids = col('id').map(String);
const lat = col('latitude').map(Number);
const a = col('a').map(Number);
const b = col('b').map(Number);
const days = col('days').map(Number);

// Stations in row order: north first. The query sorts by latitude.
const order = [];
const latOf = {};
ids.forEach((id, i) => {
  if (!(id in latOf)) {
    latOf[id] = lat[i];
    order.push(id);
  }
});
const row = Object.fromEntries(order.map((id, k) => [id, k]));

const picked = grafana.replaceVariables(STATION);
const from = Number(grafana.replaceVariables(FROM));
const to = Number(grafana.replaceVariables(TO));
const on = theme.visualization.getColorByName(COLOR_ON);
const pickedColor = theme.visualization.getColorByName(COLOR_PICKED);
const day = (ms) => new Date(ms).toISOString().slice(0, 10);
const deg = (v) => `${Math.abs(v).toFixed(2)}°${v < 0 ? 'S' : 'N'}`;

chart.off('click');
chart.on('click', (e) => {
  const id = order[e.value?.[2]];
  if (id) {
    grafana.locationService.partial({ ['var-' + VAR]: id }, true);
  }
});

const data = ids.map((id, i) => [a[i], b[i], row[id], days[i]]);

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 24, top: 8, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const [x0, x1, k, n] = p.value;
      return `<b>${order[k]}</b> · ${deg(latOf[order[k]])}<br/>${day(x0)} → ${day(x1 - 86400000)} · ${n} days<br/><span style="opacity:.7">click to choose this station</span>`;
    },
  },
  xAxis: {
    type: 'time',
    axisLabel: { color: muted, hideOverlap: true },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: order,
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: {
      color: muted,
      fontSize: 9,
      interval: (k, id) => id === picked || k % 8 === 0,
      formatter: (id) => (id === picked ? `{p|${id}}` : id),
      rich: { p: { color: pickedColor, fontWeight: 'bold', fontSize: 11 } },
    },
  },
  series: [
    {
      type: 'custom',
      encode: { x: [0, 1], y: 2 },
      data,
      renderItem: (params, api) => {
        const k = api.value(2);
        const start = api.coord([api.value(0), k]);
        const end = api.coord([api.value(1), k]);
        const h = Math.max(1, api.size([0, 1])[1] * (order[k] === picked ? 1 : 0.7));
        const inWindow = api.value(1) > from && api.value(0) < to;
        return {
          type: 'rect',
          shape: { x: start[0], y: start[1] - h / 2, width: Math.max(1, end[0] - start[0]), height: h },
          style: {
            fill: order[k] === picked ? pickedColor : on,
            opacity: order[k] === picked ? 1 : inWindow ? 0.75 : 0.3,
          },
        };
      },
      markArea: {
        silent: true,
        itemStyle: { color: 'rgba(128,128,128,0.15)', borderColor: muted, borderWidth: 1, borderType: 'dashed' },
        data: [[{ xAxis: from }, { xAxis: to }]],
      },
    },
  ],
};

// The whole network through the window: one row per station, north at the
// top, time across, and the colour how far the station has moved since the
// start of the window in the component picked with the buttons (east, north,
// up, or the horizontal distance). An earthquake shows as a vertical edge that
// spans the stretch of coast it moved; steady loading as a gradient. Blank
// cells have no data. The colour scale is symmetric around zero and
// stops at the 98th percentile, so one far-off station does not wash out the
// rest. Dotted lines are M7+ earthquakes in the window.
//
// Click a cell to choose that station. Hovering a column publishes its step to
// the dashboard's shared crosshair, by hand (Business Charts does not).

// @constants begin
const VAR = 'station';
const COMP_VAR = 'comp';
const STATION = '${station}'; // written out: a new station redraws the chart
const COMP = '${comp}';
const COMPONENTS = {
  east_mm: 'East',
  north_mm: 'North',
  up_mm: 'Up',
  horizontal_mm: 'Horizontal',
};
// Red is west, south or down; blue east, north or up. On a dark theme the
// middle is grey and the ends bright, so "did not move" stays apart from the
// background that blank cells show.
const DIVERGING_LIGHT = ['#b2182b', '#ef8a62', '#fddbc7', '#f7f7f7', '#d1e5f0', '#67a9cf', '#2166ac'];
const DIVERGING_DARK = ['#f4a582', '#d6604d', '#8c3b3b', '#4a4f5a', '#2f5f8a', '#4393c3', '#92c5de'];
const SEQUENTIAL_LIGHT = ['#fff5eb', '#fdd0a2', '#fd8d3c', '#d94801', '#7f2704'];
const SEQUENTIAL_DARK = ['#4a4f5a', '#7f2704', '#d94801', '#fd8d3c', '#fdd0a2'];
const COLOR_PICKED = 'orange';
const QUAKE_MAG = 7;
const TAG = 'gnss-heatmap'; // marks the crosshair events this chart publishes
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;

const frame = (id) => context.panel.data.series.find((f) => f.refId === id);
const col = (id, name) => {
  const f = frame(id);
  return f ? Array.from(f.fields.find((x) => x.name === name)?.values ?? []) : [];
};
const comp = COMPONENTS[grafana.replaceVariables(COMP)] ? grafana.replaceVariables(COMP) : 'east_mm';
const picked = grafana.replaceVariables(STATION);
const pickedColor = theme.visualization.getColorByName(COLOR_PICKED);

const ids = col('A', 'id').map(String);
const lat = col('A', 'latitude').map(Number);
const time = col('A', 'time').map(Number);
const value = col('A', comp).map((v) => (v == null ? null : Number(v)));

// Rows: stations north to south. Columns: the buckets, in time order.
const latOf = {};
ids.forEach((id, i) => (latOf[id] = lat[i]));
const order = Object.keys(latOf).sort((a, b) => latOf[b] - latOf[a]);
const row = Object.fromEntries(order.map((id, k) => [id, k]));
const buckets = [...new Set(time)].sort((a, b) => a - b);
const colOf = Object.fromEntries(buckets.map((t, k) => [t, k]));
const data = ids.map((id, i) => [colOf[time[i]], row[id], value[i]]).filter((d) => d[2] != null);

// A symmetric scale (or 0..max for the horizontal distance) at the 98th
// percentile of the magnitudes.
const mags = data.map((d) => Math.abs(d[2])).sort((a, b) => a - b);
const top = Math.max(1, mags.length ? mags[Math.floor(mags.length * 0.98)] : 1);
const signed = comp !== 'horizontal_mm';

const quakes = col('B', 't')
  .map((t, i) => ({ t: Number(t), mag: Number(col('B', 'mag')[i]) }))
  .filter((q) => q.mag >= QUAKE_MAG);
const bucketOf = (t) => {
  let k = 0;
  while (k + 1 < buckets.length && buckets[k + 1] <= t) {
    k++;
  }
  return k;
};

const day = (ms) => new Date(ms).toISOString().slice(0, 10);
const deg = (v) => `${Math.abs(v).toFixed(2)}°${v < 0 ? 'S' : 'N'}`;

chart.off('click');
chart.on('click', (e) => {
  const id = order[e.value?.[1]];
  if (e.seriesType === 'heatmap' && id) {
    grafana.locationService.partial({ ['var-' + VAR]: id }, true);
  }
});

const bus = grafana.eventBus;
chart.off('mouseover');
chart.off('globalout');
chart.on('mouseover', (e) => {
  const t = buckets[e.value?.[0]];
  if (e.seriesType === 'heatmap' && t != null) {
    bus.publish({ type: 'data-hover', payload: { point: { time: t } }, tags: new Set([TAG]) });
  }
});
chart.on('globalout', () => bus.publish({ type: 'data-hover-clear', payload: {}, tags: new Set([TAG]) }));

const button = (key, left) => ({
  type: 'text',
  left,
  top: 2,
  z: 10,
  cursor: 'pointer',
  style: {
    text: COMPONENTS[key],
    fill: key === comp ? theme.colors.primary.contrastText : theme.colors.text.primary,
    backgroundColor: key === comp ? theme.colors.primary.main : theme.colors.background.secondary,
    borderColor: theme.colors.border.medium,
    borderWidth: 1,
    borderRadius: 12,
    padding: [4, 10],
    font: '12px Inter, sans-serif',
  },
  onclick: () => grafana.locationService.partial({ ['var-' + COMP_VAR]: key }, true),
});

return {
  animation: false,
  backgroundColor: 'transparent',
  graphic: [
    ...Object.keys(COMPONENTS).map((key, k) => button(key, 8 + k * 86)),
    {
      type: 'text',
      left: 8 + 4 * 86 + 8,
      top: 7,
      style: {
        text: buckets.length
          ? `${COMPONENTS[comp]} shift since ${day(buckets[0])}, mm · one cell = ${
              buckets.length > 1 ? Math.round((buckets[1] - buckets[0]) / 86400000) : 1
            } day(s)`
          : 'No series for this window: run datasets/geosismos/build.sh, or pick a window inside its dates',
        fill: muted,
        font: '12px Inter, sans-serif',
      },
    },
  ],
  grid: { left: 8, right: 84, top: 34, bottom: 8, containLabel: true },
  tooltip: {
    formatter: (p) => {
      const [x, k, v] = p.value;
      const id = order[k];
      return `<b>${id}</b> · ${deg(latOf[id])}<br/>${day(buckets[x])}: ${COMPONENTS[comp]} <b>${v > 0 && signed ? '+' : ''}${v.toFixed(1)} mm</b><br/><span style="opacity:.7">click to choose this station</span>`;
    },
  },
  xAxis: {
    type: 'category',
    data: buckets,
    axisLabel: { color: muted, hideOverlap: true, formatter: (t) => day(Number(t)) },
    axisTick: { show: false },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: order,
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: {
      color: muted,
      fontSize: 9,
      interval: (k, id) => id === picked || k % 8 === 0,
      formatter: (id) => (id === picked ? `{p|${id}}` : `${id} ${deg(latOf[id])}`),
      rich: { p: { color: pickedColor, fontWeight: 'bold', fontSize: 11 } },
    },
  },
  visualMap: {
    type: 'continuous',
    min: signed ? -top : 0,
    max: top,
    calculable: false,
    orient: 'vertical',
    right: 4,
    top: 'middle',
    itemHeight: 160,
    text: [signed ? `+${top.toFixed(0)} mm` : `${top.toFixed(0)} mm`, signed ? `−${top.toFixed(0)}` : '0'],
    textStyle: { color: muted, fontSize: 10 },
    inRange: {
      color: signed ? (theme.isDark ? DIVERGING_DARK : DIVERGING_LIGHT) : theme.isDark ? SEQUENTIAL_DARK : SEQUENTIAL_LIGHT,
    },
  },
  series: [
    {
      type: 'heatmap',
      data,
      progressive: 0,
      emphasis: { itemStyle: { borderColor: theme.colors.text.primary, borderWidth: 1 } },
      markLine: {
        silent: true,
        symbol: 'none',
        lineStyle: { type: 'dotted', color: theme.colors.text.primary, width: 1 },
        label: { formatter: (p) => `M${p.data.mag}`, color: theme.colors.text.primary, fontSize: 10 },
        data: [
          ...quakes.map((q) => ({ xAxis: bucketOf(q.t), mag: q.mag })),
          // the chosen station's row
          ...(picked in row
            ? [{ yAxis: picked, mag: null, label: { show: false }, lineStyle: { type: 'dashed', color: pickedColor, width: 1 } }]
            : []),
        ],
      },
    },
  ],
};

// The chosen station's daily position, east, north and up, each on its own
// axis, in millimetres from its first good day in the window: so the last value
// of the east and north lines is the arrow on the map. The dashed line is the
// least-squares trend over the window and its slope is in each title, in mm per
// year. When an M7+ earthquake within RADIUS_KM falls inside the window a trend
// means nothing, so the title gives that event's jump instead: the mean of the
// good days just after it minus the mean of those just before.
//
// Grey dots are the days the source flags as outliers: drawn, but left out of
// the line and the trend, and the axis is scaled to the good days, so an
// outlier far off the line is cut at the edge rather than flattening it.
// A vertical line is an M6+ earthquake within RADIUS_KM of the station; the
// shaded band is the time brush, the span the map's arrows measure.
//
// Scroll or drag on the chart to zoom into days; double click to reset.
//
// It takes part in the dashboard's shared crosshair by hand (Business Charts
// does not): hovering it publishes the day, tagged so it never answers itself,
// and a day hovered on the brush, the cards or the network map shows its tip.

// @constants begin
const COMPONENTS = [
  { key: 'east', label: 'East', out: 'out_e', color: '#E08A48' },
  { key: 'north', label: 'North', out: 'out_n', color: '#3F6C9C' },
  { key: 'up', label: 'Up', out: 'out_u', color: '#2A9D8F' },
];
const RADIUS_KM = 500; // must match the radius in query B
const STATION = '${station}'; // written out: a new station redraws the chart
const BRUSH_FROM = '${t0}'; // the time brush, shaded: the span the map's arrows measure
const BRUSH_TO = '${t1}';
const YEAR = 365.25 * 86400000;
const TAG = 'gnss-series'; // marks the crosshair events this chart publishes
const JUMP_MAG = 7; // an event this large inside the window: show its jump, not a trend
const JUMP_DAYS = 3; // good days averaged on each side of it
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;

const frame = (id) => context.panel.data.series.find((f) => f.refId === id);
const col = (id, name) => {
  const f = frame(id);
  return f ? Array.from(f.fields.find((x) => x.name === name)?.values ?? []) : [];
};
const num = (v) => (v == null || v === '' ? null : Number(v));
const time = col('A', 'time').map(Number);
const station = grafana.replaceVariables(STATION);
const brush = [Date.parse(grafana.replaceVariables(BRUSH_FROM)), Date.parse(grafana.replaceVariables(BRUSH_TO))];

const quakes = col('B', 't').map((t, i) => ({
  t: Number(t),
  mag: Number(col('B', 'mag')[i]),
  km: Number(col('B', 'km')[i]),
  place: String(col('B', 'place')[i]),
}));

// Ordinary least squares of value on time, over the good days only.
const trend = (xs, ys) => {
  const pts = xs.map((x, i) => [x, ys[i]]).filter((p) => p[1] != null);
  if (pts.length < 10) {
    return null;
  }
  const n = pts.length;
  const mx = pts.reduce((s, p) => s + p[0], 0) / n;
  const my = pts.reduce((s, p) => s + p[1], 0) / n;
  const sxy = pts.reduce((s, p) => s + (p[0] - mx) * (p[1] - my), 0);
  const sxx = pts.reduce((s, p) => s + (p[0] - mx) * (p[0] - mx), 0);
  const slope = sxx ? sxy / sxx : 0;
  const x0 = pts[0][0];
  const x1 = pts[n - 1][0];
  return { perYear: slope * YEAR, line: [[x0, my + slope * (x0 - mx)], [x1, my + slope * (x1 - mx)]] };
};

// The largest nearby event big enough to break a trend, if any.
const big = quakes.filter((q) => q.mag >= JUMP_MAG).sort((x, y) => y.mag - x.mag)[0];

// Mean of the good days just after the event minus those just before.
const jump = (xs, ys, t) => {
  const before = xs.map((x, i) => [x, ys[i]]).filter((p) => p[1] != null && p[0] < t).slice(-JUMP_DAYS);
  const after = xs.map((x, i) => [x, ys[i]]).filter((p) => p[1] != null && p[0] > t).slice(0, JUMP_DAYS);
  if (!before.length || !after.length) {
    return null;
  }
  const mean = (a) => a.reduce((s, p) => s + p[1], 0) / a.length;
  return mean(after) - mean(before);
};

const fmt = (v) => (v == null ? '–' : (v > 0 ? '+' : '') + v.toFixed(1));
const GAP = 7; // percent between the three grids, where each title sits
const H = (100 - 9 - 6 - 2 * GAP) / 3;
const top = (k) => 9 + k * (H + GAP);

const grids = [];
const xAxes = [];
const yAxes = [];
const series = [];
const titles = [];

COMPONENTS.forEach((c, k) => {
  const raw = col('A', `${c.key}_mm`).map(num);
  const out = col('A', c.out).map(Number);
  const good = raw.map((v, i) => (out[i] ? null : v));
  const fit = big ? null : trend(time, good);
  const step = big ? jump(time, good, big.t) : null;
  const vals = good.filter((v) => v != null);
  const lo = vals.length ? Math.min(...vals) : 0;
  const hi = vals.length ? Math.max(...vals) : 1;
  const pad = Math.max((hi - lo) * 0.08, 1);
  grids.push({ left: 64, right: 24, top: `${top(k)}%`, height: `${H}%` });
  xAxes.push({
    type: 'time',
    gridIndex: k,
    axisLabel: { show: k === COMPONENTS.length - 1, color: muted, hideOverlap: true },
    axisTick: { show: k === COMPONENTS.length - 1 },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
    splitLine: { show: false },
  });
  yAxes.push({
    type: 'value',
    gridIndex: k,
    min: Math.floor(lo - pad),
    max: Math.ceil(hi + pad),
    name: 'mm',
    nameLocation: 'middle',
    nameGap: 44,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, showMinLabel: false, showMaxLabel: false },
    splitNumber: 3,
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  });
  titles.push({
    left: 64,
    top: `${top(k) - 6}%`,
    text: `${c.label}  ${
      fit ? fmt(fit.perYear) + ' mm/yr trend' : step != null ? `${fmt(step)} mm jump at the M${big.mag}` : ''
    }`,
    textStyle: { fontSize: 12, fontWeight: 'bold', color: c.color },
  });
  series.push({
    name: c.label,
    type: 'line',
    xAxisIndex: k,
    yAxisIndex: k,
    showSymbol: false,
    connectNulls: false,
    lineStyle: { width: 1.5, color: c.color },
    itemStyle: { color: c.color },
    data: time.map((t, i) => [t, good[i]]),
    markArea: brush.every(Number.isFinite)
      ? { silent: true, itemStyle: { color: 'rgba(128,128,128,0.15)' }, data: [[{ xAxis: brush[0] }, { xAxis: brush[1] }]] }
      : undefined,
    markLine: {
      silent: true,
      symbol: 'none',
      lineStyle: { type: 'dotted', color: theme.colors.text.primary, width: 1, opacity: 0.6 },
      label: {
        show: k === 0,
        formatter: (p) => (p.data.mag >= JUMP_MAG ? `M${p.data.mag}` : ''),
        color: theme.colors.text.primary,
        fontSize: 10,
        position: 'insideEndTop',
      },
      data: quakes.map((q) => ({ xAxis: q.t, mag: q.mag })),
    },
  });
  series.push({
    name: `${c.label} outliers`,
    type: 'scatter',
    xAxisIndex: k,
    yAxisIndex: k,
    symbolSize: 3,
    clip: true,
    itemStyle: { color: 'rgba(128,128,128,0.55)' },
    tooltip: { show: false },
    data: time.map((t, i) => (out[i] && raw[i] != null ? [t, raw[i]] : null)).filter(Boolean),
  });
  if (fit) {
    series.push({
      name: `${c.label} trend`,
      type: 'line',
      xAxisIndex: k,
      yAxisIndex: k,
      symbol: 'none',
      silent: true,
      tooltip: { show: false },
      lineStyle: { type: 'dashed', width: 1, color: theme.colors.text.primary, opacity: 0.7 },
      data: fit.line,
    });
  }
});

// The shared crosshair, by hand.
const bus = grafana.eventBus;
const zr = chart.getZr();
let published = null;
const hoverAt = (ms) => {
  if (ms === published) {
    return;
  }
  published = ms;
  bus.publish(
    ms === null
      ? { type: 'data-hover-clear', payload: {}, tags: new Set([TAG]) }
      : { type: 'data-hover', payload: { point: { time: ms } }, tags: new Set([TAG]) }
  );
};
zr.off('mousemove');
zr.off('globalout');
zr.on('mousemove', (e) => {
  const at = [e.offsetX, e.offsetY];
  const k = [0, 1, 2].find((g) => chart.containPixel({ gridIndex: g }, at));
  if (k === undefined || e.event?.buttons) {
    hoverAt(null);
    return;
  }
  const ms = Math.round(chart.convertFromPixel({ gridIndex: k }, at)[0] / 86400000) * 86400000;
  hoverAt(Number.isFinite(ms) ? ms : null);
});
zr.on('globalout', () => hoverAt(null));
// Follow the others: the nearest day's tip. One subscription per chart, renewed
// on every redraw.
chart.__crosshair?.unsubscribe();
chart.__crosshair = bus.getStream({ type: 'data-hover' }).subscribe((event) => {
  if (event.tags?.has?.(TAG) || !time.length) {
    return;
  }
  const ms = Number(event.payload?.point?.time);
  if (!Number.isFinite(ms) || ms < time[0] || ms > time[time.length - 1]) {
    return;
  }
  let i = 0;
  while (i + 1 < time.length && time[i + 1] <= ms) {
    i++;
  }
  chart.dispatchAction({ type: 'showTip', seriesIndex: 0, dataIndex: i });
});
chart.__crosshairClear?.unsubscribe();
chart.__crosshairClear = bus.getStream({ type: 'data-hover-clear' }).subscribe((event) => {
  if (!event.tags?.has?.(TAG)) {
    chart.dispatchAction({ type: 'hideTip' });
  }
});

const none = !time.length;

return {
  animation: false,
  backgroundColor: 'transparent',
  title: none
    ? {
        left: 'center',
        top: 'middle',
        text: station ? `No daily positions for ${station} in this window` : 'Pick a station on the map, in the table or in the dropdown',
        textStyle: { color: muted, fontSize: 14, fontWeight: 'normal' },
      }
    : titles,
  axisPointer: { link: [{ xAxisIndex: 'all' }] },
  tooltip: {
    trigger: 'axis',
    formatter: (items) => {
      const i = items[0]?.dataIndex;
      if (i == null || time[i] == null) {
        return '';
      }
      const rows = COMPONENTS.map((c) => {
        const v = num(col('A', `${c.key}_mm`)[i]);
        const flagged = Number(col('A', c.out)[i]) ? ' <span style="opacity:.6">(outlier)</span>' : '';
        return `<span style="color:${c.color}">●</span> ${c.label} <b>${fmt(v)} mm</b>${flagged}`;
      });
      const near = quakes.filter((q) => Math.abs(q.t - time[i]) < 43200000);
      return (
        `<b>${station} · ${new Date(time[i]).toISOString().slice(0, 10)}</b><br/>` +
        rows.join('<br/>') +
        near.map((q) => `<br/>M${q.mag} ${q.place}, ${q.km} km away`).join('')
      );
    },
  },
  dataZoom: [{ type: 'inside', xAxisIndex: COMPONENTS.map((c, k) => k), filterMode: 'none' }],
  grid: grids,
  xAxis: xAxes,
  yAxis: yAxes,
  series,
};

// Pick the window: every M6+ earthquake since the GNSS record began, as dots on
// a time line (size is magnitude; shallow events, the ones that move the ground
// a station stands on, in red, deeper ones in grey). The band is the window the
// map and the series are showing.
//
// Click a dot: the window becomes the week before to the week after that event,
// so the arrows are its coseismic jump. Shift-click: the two years after it,
// the postseismic slip. The buttons give the usual long windows.

// @constants begin
const DAY = 86400000;
const AROUND_DAYS = 7; // a click: this many days on each side of the event
const POST_YEARS = 2; // a shift-click: this long after the event
const LABEL_MAG = 7.4; // events at least this large carry their name
const SHALLOW_KM = 70; // interface and crustal events: the ones GNSS sees
const COLOR_SHALLOW = 'red';
const COLOR_DEEP = 'text'; // the theme's secondary text colour
// written out so a time range change redraws the band
const FROM = '${__from}';
const TO = '${__to}';
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;
const color = (name) => (name === 'text' ? muted : theme.visualization.getColorByName(name));

const frame = (id) => context.panel.data.series.find((f) => f.refId === id);
const col = (id, name) => {
  const f = frame(id);
  return f ? Array.from(f.fields.find((x) => x.name === name)?.values ?? []) : [];
};
const t = col('A', 't').map(Number);
const mag = col('A', 'mag').map(Number);
const depth = col('A', 'depth_km').map(Number);
const place = col('A', 'place').map(String);
const first = Number(col('B', 'first')[0]) || Date.UTC(2013, 0, 1);
const last = Number(col('B', 'published')[0]) || Date.now();

const from = Number(grafana.replaceVariables(FROM));
const to = Number(grafana.replaceVariables(TO));
const day = (ms) => new Date(ms).toISOString().slice(0, 10);
const clamp = (ms) => Math.min(Math.max(ms, first), last + DAY);

const setWindow = (a, b) => {
  grafana.locationService.partial({ from: String(Math.round(clamp(a))), to: String(Math.round(clamp(b))) }, true);
};

const shortPlace = (p) => p.replace(/^[0-9]+ km [NSEW]+ of /, '').replace(/, (Chile|Argentina|Peru|Bolivia)$/, '');

const points = t.map((ms, i) => ({
  value: [ms, mag[i]],
  shallow: depth[i] < SHALLOW_KM,
  name: `${shortPlace(place[i])} ${new Date(ms).getUTCFullYear()}`,
  i,
}));

chart.off('click');
chart.on('click', (e) => {
  if (e.seriesType !== 'scatter') {
    return;
  }
  const ms = t[e.data.i];
  if (e.event?.event?.shiftKey) {
    setWindow(ms + AROUND_DAYS * DAY, ms + AROUND_DAYS * DAY + POST_YEARS * 365.25 * DAY);
  } else {
    setWindow(ms - AROUND_DAYS * DAY, ms + AROUND_DAYS * DAY);
  }
});

const button = (label, left, onclick) => ({
  type: 'text',
  left,
  top: 4,
  z: 10,
  cursor: 'pointer',
  style: {
    text: label,
    fill: theme.colors.text.primary,
    backgroundColor: theme.colors.background.secondary,
    borderColor: theme.colors.border.medium,
    borderWidth: 1,
    borderRadius: 12,
    padding: [4, 10],
    font: '12px Inter, sans-serif',
  },
  onclick,
});

const series = (shallow) => ({
  name: shallow ? `shallow (< ${SHALLOW_KM} km)` : 'deeper',
  type: 'scatter',
  cursor: 'pointer',
  data: points.filter((p) => p.shallow === shallow),
  symbolSize: (v) => Math.max(4, (v[1] - 5.6) * (v[1] - 5.6) * 7),
  itemStyle: {
    color: color(shallow ? COLOR_SHALLOW : COLOR_DEEP),
    opacity: shallow ? 0.85 : 0.45,
    borderColor: theme.colors.background.primary,
    borderWidth: 1,
  },
  label: {
    show: true,
    position: 'top',
    color: theme.colors.text.primary,
    fontSize: 11,
    formatter: (p) => (p.value[1] >= LABEL_MAG ? `${p.data.name} · M${p.value[1]}` : ''),
  },
  labelLayout: { hideOverlap: true },
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 52, bottom: 4, containLabel: true },
  legend: {
    top: 6,
    right: 8,
    textStyle: { color: muted },
    selectedMode: false,
    data: [`shallow (< ${SHALLOW_KM} km)`, 'deeper'],
  },
  graphic: [
    button('Whole record', 8, () => setWindow(first, last + DAY)),
    button('2017 → last day', 112, () => setWindow(Date.UTC(2017, 0, 1), last + DAY)),
    button('Last 12 months', 232, () => setWindow(last + DAY - 365 * DAY, last + DAY)),
    {
      type: 'text',
      left: 352,
      top: 9,
      style: {
        text: `window ${day(from)} → ${day(Math.min(to, last + DAY))} · click an event for its jump, shift-click for the two years after`,
        fill: muted,
        font: '12px Inter, sans-serif',
      },
    },
  ],
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      if (p.seriesType !== 'scatter') {
        return '';
      }
      const i = p.data.i;
      return (
        `<b>M${mag[i]} · ${place[i]}</b><br/>${new Date(t[i]).toISOString().slice(0, 16).replace('T', ' ')} UTC · ${depth[i]} km deep` +
        `<br/><span style="opacity:.7">click: ${AROUND_DAYS} days each side · shift-click: the ${POST_YEARS} years after</span>`
      );
    },
  },
  xAxis: {
    type: 'time',
    min: first,
    max: last + DAY,
    axisLabel: { color: muted, hideOverlap: true },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    min: 5.8,
    max: 8.9,
    interval: 1,
    name: 'M',
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [
    series(false),
    {
      ...series(true),
      markArea: {
        silent: true,
        itemStyle: { color: 'rgba(128,128,128,0.18)', borderColor: muted, borderWidth: 1, borderType: 'dashed' },
        data: [[{ xAxis: Math.max(from, first) }, { xAxis: Math.min(to, last + DAY) }]],
      },
    },
  ],
};
